// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(msg.sender != address(0));
        // the caller is the current owner, so the call must succeed in both versions;
        // the rule constrains the RETURN VALUE, not the revert behaviour.
        vm.prank(msg.sender);
        bool ok = c.setOwner(newOwner);
        assertTrue(ok, "successful setOwner by owner must return true");
    }
}

